/// Resolves a human-typed `--package` argument (bare or ecosystem-qualified)
/// through the one selector resolver, [`crate::IdentityIndex::resolve`] --
/// a bare name is accepted only when it names exactly one package.
fn resolve_selected_package(
    all_packages: &[&callisto_model::Package],
    identity: &crate::IdentityIndex,
    raw: &str,
) -> Result<PackageId, GraphError> {
    ConfigError::require_qualified(raw, "--package")?;
    let resolved = identity.resolve(raw)?;
    if all_packages.iter().any(|p| p.id == resolved) {
        Ok(resolved)
    } else {
        Err(GraphError::UnknownPackage { id: resolved })
    }
}

    let mut entries = Vec::new();
    let mut summary = args.summary.clone();

    if !args.packages.is_empty() {
        // Non-interactive mode (flags supplied via CLI or agent)
        for pkg_str in args.packages {
            let (name, sev_str) = pkg_str
                .rsplit_once(':')
                .ok_or_else(|| CliError::AddInvalidPackageSpec { spec: pkg_str.clone() })?;

            let severity = parse_severity(sev_str)?;

            // Resolves by any registered native name (not just a package's
            // primary/display name), reporting E102/E103 on a miss or
            // ecosystem-ambiguous bare name.
            callisto_graph::ConfigError::require_qualified(name, "--package")
                .map_err(callisto_graph::GraphError::Config)?;
            let resolved = ws.identity.resolve(name)?;

            entries.push(Entry {
                // Use display_name() so "cargo/foo" is preserved, not just "foo".
                // In a polyglot workspace, the bare name is ambiguous across ecosystems.
                name: resolved.display_name(),
                severity,
            });
        }
    } else if tty::is_interactive() {
        let all_packages = collect_package_names(ws.graph.packages());
        let Some((chosen, written)) = run_wizard(&all_packages, summary.clone(), &mut TerminalAddPrompter)? else {
            return Ok(ExitCode::SUCCESS);
        };
        entries = chosen;
        summary = Some(written);
    } else {
        return Err(CliError::NotATty);
    }

    let raw_summary = summary.ok_or(CliError::AddSummaryRequired)?;
    let summary_text = validate_summary(&raw_summary)?;
    let changeset = Changeset {
        entries,
                ecosystem: Ecosystem::Pypi,
                name: "ambiguous-lib".to_string(),
            },
        );
        let mut diagnostics = Vec::new();
        let result = index.resolve_native_with_fallback(Ecosystem::Npm, "ambiguous-lib", &mut diagnostics);
        assert!(result.is_none());
        assert_eq!(diagnostics.len(), 1, "exactly one diagnostic, not zero and not two");
        assert!(
            diagnostics[0].message.contains("cargo/ambiguous-lib")
                && diagnostics[0].message.contains("pypi/ambiguous-lib")
        );
    }

    #[test]
    fn resolve_qualified_selector_is_exact_and_misses_report_e102() {
        let mut index = IdentityIndex::default();
        let npm_only = PackageId::Bare("foo".to_string());
        index
            .native
            .insert((Ecosystem::Npm, "foo".to_string()), npm_only.clone());

        // repro/ws-qual: `cargo/foo` must not select the npm-only `foo`.
        let err = index.resolve("cargo/foo").unwrap_err();
        assert!(
            matches!(err, GraphError::UnknownPackage { .. }),
            "expected E102, got {err:?}"
        );

        assert_eq!(index.resolve("npm/foo").unwrap(), npm_only);
        let err = index.resolve("npm:foo").unwrap_err();
        assert!(
            matches!(&err, GraphError::Config(ConfigError::ColonReference { canonical, .. }) if canonical == "npm/foo"),
            "the colon form must be rejected with the slash form named, got {err:?}"
        );
    }

