fn did_you_mean<'a>(missing: &PackageId, known: impl IntoIterator<Item = &'a PackageId>) -> String {
    let wanted = missing.name().to_lowercase();
    let limit = (wanted.chars().count() / 3).max(1);
    let mut close: Vec<(usize, bool, String)> = known
        .into_iter()
